            [8,8,3,9,3,3,3,3,8,8],
            [8,8,3,3,3,3,3,3,8,8],
            [8]*10, [8]*10
        ]

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Extract each foreground fragment, retaining background-colored cells
    # inside its rectangular bounding box.
    seen = [[False] * w for _ in range(h)]
    pieces = []
    for r in range(h):
        for c in range(w):
            if seen[r][c] or grid[r][c] == bg:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            not seen[ny][nx] and grid[ny][nx] != bg):
                        seen[ny][nx] = True
                        q.append((ny, nx))
            y0 = min(y for y, x in cells)
            y1 = max(y for y, x in cells)
            x0 = min(x for y, x in cells)
            x1 = max(x for y, x in cells)
            a = [[bg] * (x1 - x0 + 1) for _ in range(y1 - y0 + 1)]
            for y, x in cells:
                a[y-y0][x-x0] = grid[y][x]
            pieces.append(a)

    if not pieces:
        return [row[:] for row in grid]

    area = sum(len(a) * len(a[0]) for a in pieces)

    def rotate(a):
        return [list(row) for row in zip(*a[::-1])]

    def get_orientations(a, allow_rotate):
        result = [a]
        if allow_rotate:
            cur = a
            for _ in range(3):
                cur = rotate(cur)
                if cur not in result:
                    result.append(cur)
        return result

    def solve(H, W, allow_rotate, limit):
        if H * W != area:
            return None

        variants = [get_orientations(a, allow_rotate) for a in pieces]
        board = [[None] * W for _ in range(H)]
        occupied = [[False] * W for _ in range(H)]
        used = [False] * len(pieces)
        nodes = [0]
        result = [None]

        def first_empty():
            for y in range(H):
                for x in range(W):
                    if not occupied[y][x]:
                        return y, x
            return None

        def search(done):
            if done == len(pieces):
                result[0] = [row[:] for row in board]
                return True
            nodes[0] += 1
            if nodes[0] > limit:
                return False

            pos = first_empty()
            if pos is None:
                return False
            y0, x0 = pos
            choices = []

            for i, orientations in enumerate(variants):
                if used[i]:
                    continue
                for oi, a in enumerate(orientations):
                    ah, aw = len(a), len(a[0])
                    if y0 + ah > H or x0 + aw > W:
                        continue

                    good = True
                    matches = 0
                    for y in range(ah):
                        for x in range(aw):
                            yy, xx = y0 + y, x0 + x
                            if occupied[yy][xx]:
                                good = False
                                break
                            v = a[y][x]
                            for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                                ny, nx = yy + dy, xx + dx
                                if 0 <= ny < H and 0 <= nx < W and occupied[ny][nx]:
                                    if board[ny][nx] != v:
                                        good = False
                                        break
                                    matches += 1
                            if not good:
                                break
                        if not good:
                            break
                    if good:
                        # Prefer a piece whose dimensions and edges fit the
                        # already placed neighbors most specifically.
                        choices.append((matches, i, oi, a))

            choices.sort(key=lambda t: t[0], reverse=True)
            for matches, i, oi, a in choices:
                ah, aw = len(a), len(a[0])
                for y in range(ah):
                    for x in range(aw):
                        occupied[y0+y][x0+x] = True
                        board[y0+y][x0+x] = a[y][x]
                used[i] = True
                if search(done + 1):
                    return True
                used[i] = False
                for y in range(ah):
                    for x in range(aw):
                        occupied[y0+y][x0+x] = False
                        board[y0+y][x0+x] = None
            return False

        search(0)
        return result[0]

    dims = []
    for a in range(1, area + 1):
        if area % a == 0:
            b = area // a
            if a <= 30 and b <= 30:
                dims.append((a, b))
    dims.sort(key=lambda d: (abs(d[0] / d[1] - 0.72), abs(d[0] - d[1])))

    assembled = None
    chosen = None
    for allow_rotate in (False, True):
        for H, W in dims:
            assembled = solve(H, W, allow_rotate, 1500000)
            if assembled is not None:
                chosen = (H, W)
                break
        if assembled is not None:
            break

    if assembled is None:
        return [row[:] for row in grid]

    H, W = chosen
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    cy = sum(r for r, c in points) / len(points)
    cx = sum(c for r, c in points) / len(points)
    top = max(0, min(h-H, round(cy - (H-1)/2)))
    left = max(0, min(w-W, round(cx - (W-1)/2)))

    out = [[bg] * w for _ in range(h)]
    for y in range(H):
        for x in range(W):
            out[top+y][left+x] = assembled[y][x]
    return out
